// Dummy recruitment pipeline (fictional). Each row = [client, role, furthest stage reached, number of candidates].
// "Held" = sitting in the database, never contacted, so it has no client or role.
const rows = [
  [null, null, 'Held', 40],
  ['Northgate Capital', 'Quant Researcher', 'Contacted', 6],
  ['Northgate Capital', 'Quant Researcher', 'Engaged', 4],
  ['Northgate Capital', 'Quant Researcher', 'Submitted', 3],
  ['Northgate Capital', 'Quant Researcher', 'Interview', 2],
  ['Northgate Capital', 'Quant Researcher', 'Offer', 1],
  ['Northgate Capital', 'Quant Researcher', 'Placed', 1],
  ['Helix Trading', 'Low-Latency Developer', 'Contacted', 5],
  ['Helix Trading', 'Low-Latency Developer', 'Engaged', 3],
  ['Helix Trading', 'Low-Latency Developer', 'Submitted', 2],
  ['Helix Trading', 'Low-Latency Developer', 'Interview', 1],
  ['Orbit Systems', 'Infrastructure Engineer', 'Contacted', 4],
  ['Orbit Systems', 'Infrastructure Engineer', 'Engaged', 2],
  ['Orbit Systems', 'Infrastructure Engineer', 'Submitted', 1],
  ['Orbit Systems', 'Infrastructure Engineer', 'Sourced?', 1],
];
const out = [];
let n = 1;
for (const [client, role, stage, count] of rows) {
  for (let i = 0; i < count; i++) out.push({ json: { id: 'P' + String(n++).padStart(3, '0'), client, role, furthest_stage: stage } });
}
return out;

// Pipeline report (n8n Code node, "Run once for all items").
// Keeps "held in database" separate from the contacted -> placed funnel. Unknown stages are reported, never silently counted.
const ORDER = ['Held', 'Contacted', 'Engaged', 'Submitted', 'Interview', 'Offer', 'Placed'];
const rank = Object.fromEntries(ORDER.map((s, i) => [s, i]));
const rows = $input.all().map((i) => i.json);

const known = rows.filter((r) => r.furthest_stage in rank);
const unknown = rows.filter((r) => !(r.furthest_stage in rank));
const held = known.filter((r) => r.furthest_stage === 'Held').length;
const active = known.filter((r) => r.furthest_stage !== 'Held');

// "Reached" = furthest stage is this one or later (cumulative funnel).
const reached = (list, stage) => list.filter((r) => rank[r.furthest_stage] >= rank[stage]).length;
const pct = (a, b) => (b === 0 ? null : Math.round((a / b) * 1000) / 10);

const funnelFor = (list) => {
  const steps = ORDER.slice(1).map((s) => ({ stage: s, reached: reached(list, s) }));
  steps.forEach((s, i) => { s.conversion_from_previous_pct = i === 0 ? null : pct(s.reached, steps[i - 1].reached); });
  return steps;
};

const byRole = {};
active.forEach((r) => {
  const key = r.client + ' | ' + r.role;
  (byRole[key] = byRole[key] || []).push(r);
});

return [{
  json: {
    held_in_database: held,
    contacted_and_beyond: reached(active, 'Contacted'),
    funnel: funnelFor(active),
    by_role: Object.entries(byRole).map(([k, list]) => {
      const [client, role] = k.split(' | ');
      return { client, role, funnel: funnelFor(list) };
    }),
    data_quality: {
      unrecognised_stage_records: unknown.map((r) => ({ id: r.id, stage: r.furthest_stage })),
      note: unknown.length ? 'These records are NOT counted in any funnel step. Fix their stage in the source system.' : 'All stages recognised.',
    },
  },
}];

// Weekly digest text (n8n Code node). Turns the report into a short message a person can read in 30 seconds.
const r = $input.first().json;
const line = (s) => s.stage.padEnd(10) + String(s.reached).padStart(3) + (s.conversion_from_previous_pct === null ? '' : '   (' + s.conversion_from_previous_pct + '% of previous step)');
const parts = [];
parts.push('PIPELINE DIGEST');
parts.push('Held in database (not contacted): ' + r.held_in_database);
parts.push('Contacted or further: ' + r.contacted_and_beyond);
parts.push('');
parts.push('Overall funnel (candidates who reached each stage)');
r.funnel.forEach((s) => parts.push('  ' + line(s)));
parts.push('');
parts.push('By client and role');
r.by_role.forEach((b) => {
  const get = (st) => b.funnel.find((x) => x.stage === st).reached;
  parts.push('  ' + b.client + ' / ' + b.role + ': contacted ' + get('Contacted') + ', engaged ' + get('Engaged') + ', submitted ' + get('Submitted') + ', interview ' + get('Interview') + ', offer ' + get('Offer') + ', placed ' + get('Placed'));
});
if (r.data_quality.unrecognised_stage_records.length) {
  parts.push('');
  parts.push('DATA CHECK: ' + r.data_quality.unrecognised_stage_records.length + ' record(s) have an unrecognised stage and are not counted: ' + r.data_quality.unrecognised_stage_records.map((x) => x.id + ' ("' + x.stage + '")').join(', '));
}
return [{ json: { digest_text: parts.join('\n'), report: r } }];
